                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TENANT_EXT_USERS_ORG_ASSO_V" ("EXT_USER_ID", "GENDER", "STAFF_LEVEL", "HIRED_DATE", "LEADER_EXT_USER_ID", "LEADER_SYNC_USER_ID", "LEADER_EXT_USER_NAME", "CREATED_BY", "CREATION_DATE", "UPDATED_BY", "UPDATE_DATE", "REMARK", "JOB_NUMBER", "TENANT_ID", "SYNC_USER_ID", "UNIONID", "TITLE", "NAME", "AVATAR", "STATE_CODE", "MOBILE", "EMAIL", "TYPE", "IS_EXT_USER", "JOB_LEVEL", "JOB_LEVEL_CODE", "EXT_ORG_ID", "RELATED_TYPE", "IS_MAIN_ORG", "EXT_ORG_NAME", "PARENT_ID", "IS_EXT_ORG", "LAST_LOGIN_DATE") AS     
  select u.ext_user_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       u.GENDER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       u.STAFF_LEVEL,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       u.HIRED_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       u.LEADER_EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       lu.SYNC_USER_ID as LEADER_SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       lu.NAME         as LEADER_EXT_USER_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       u.created_by,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       u.creation_date,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       u.updated_by,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       u.update_date,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       u.remark,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       u.JOB_NUMBER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       u.tenant_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       u.sync_user_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       u.unionid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       u.title,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       u.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       u.avatar,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       u.state_code,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       u.mobile,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       u.email,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       u.type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       u.is_ext_user,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       uo.job_level,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       uo.JOB_LEVEL_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       uo.ext_org_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       uo.RELATED_TYPE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       uo.IS_MAIN_ORG,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       o.NAME          as ext_org_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       o.parent_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       o.is_ext_org,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       u.LAST_LOGIN_DATE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
from TENANT_EXT_USERS u                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         inner join TENANT_EXT_USER_ORG_ASSO uo on u.EXT_USER_ID = uo.EXT_USER_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         inner join TENANT_EXT_ORG o on uo.EXT_ORG_ID = o.EXT_ORG_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         left join TENANT_EXT_USERS lu on lu.EXT_USER_ID = u.LEADER_EXT_USER_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
where u.DEL_FLAG = 0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
  and u.IS_LEAVE = 0;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           

